args.CommandLine:
$bashrc = "$env:USERPROFILE\.bashrc"
if (-not (Test-Path $bashrc)) { New-Item -ItemType File -Path $bashrc -Force }
$content = Get-Content $bashrc -Raw -ErrorAction SilentlyContinue
if ($content -notmatch "\.local/bin") {
    Add-Content -Path $bashrc -Value "`nexport PATH=`"`$HOME/.local/bin:`$PATH`"`n"
}

# Cập nhật PATH vĩnh viễn cho user Windows
$currentPath = [Environment]::GetEnvironmentVariable("PATH", [EnvironmentVariableTarget]::User)
if ($currentPath -notmatch "\.local\\bin") {
    [Environment]::SetEnvironmentVariable("PATH", "$env:USERPROFILE\.local\bin;$currentPath", [EnvironmentVariableTarget]::User)
}
Write-Output "PATH configured successfully"
